import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`product-photo-audit`,heroTitle:`Audit your product photos in minutes`,heroSubtitle:`Perplexity Computer evaluates every product photo against platform best practices, scores each image, and delivers a shot-by-shot reshoot brief with specific improvement instructions.`,inputUrlCta:`Audit my photos`,inputUrlPlaceholder:`e.g. https://yourstore.com/products`,inputUrlPrefill:`Go to {url} and evaluate every product photo against platform best practices. (1) For each listing, assess background quality (white vs lifestyle), image dimensions and resolution, lighting consistency, and angle coverage. (2) Check for required shot types — hero image, lifestyle context, scale reference, detail/texture close-up, infographic overlay, and packaging shot. (3) Score each image on a 1-10 scale across background, lighting, composition, and platform compliance. (4) Identify the top 3 improvement opportunities per listing that would have the biggest impact on conversion. (5) Write a specific reshoot brief for each underperforming image — describing the exact shot, background, lighting setup, and props needed. (6) Deliver a complete audit report with image scores, missing shot types, and prioritized reshoot briefs for every product.`,heroOverlaySteps:[`Evaluating every product photo for background, lighting, and composition`,`Checking for required shot types and platform compliance`,`Scoring each image and identifying top improvement opportunities`,`Complete audit with image scores and reshoot briefs — ready to act`],generatingSteps:[`Visiting {url} to analyze every product photo across your listings`,`Designing an agent to evaluate images against platform best practices`,`Configuring scoring and gap analysis for shot types and quality`,`Setting up deliverable with image scores, reshoot briefs, and priority recommendations`],featureSectionTitle:`From listing to reshoot brief`,featureCardTitles:[`Connects to your e-commerce stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Amazon, Shopify, Etsy — Computer plugs into your tools so photo audits, scores, and reshoot briefs flow into one workflow.`,`Image scores. Reshoot briefs. Improvement instructions. Missing shot checklists. Computer delivers a complete photo audit your team can execute immediately.`],capabilitySectionTitle:`Your product photography director, on autopilot`,capabilitySectionSubtitle:`Paste your store URL, step away, come back to a complete photo audit.`,capabilityCards:[{title:`Image Analysis`,description:`Computer can evaluate every product photo — assessing background quality, lighting, composition, resolution, and angle coverage against platform standards.`},{title:`Platform Best Practices`,description:`Computer can check each listing for required shot types — hero image, lifestyle context, scale reference, detail close-up, infographic overlay, and packaging.`},{title:`Score Card`,description:`Computer can score every image on a 1-10 scale across multiple quality dimensions — and identify the top improvement opportunities per listing.`},{title:`Connect Your Tools`,description:`Computer can read from Amazon, Shopify, Etsy, Google Drive, and more — build workflows across your entire e-commerce and creative stack.`},{title:`Remember & Learn`,description:`Computer can remember your brand style, past audits, and top-performing images across sessions — so every review builds on what converts.`},{title:`Ongoing Monitoring`,description:`Computer can monitor your listings for new photos, competitor visual strategies, and platform guideline changes — and alert you when an update is needed.`}]});export{t as default};
